import random
from itertools import combinations

def bfs_dist(adj, s, t, maxd):
    # returns shortest distance from s to t in current graph, or maxd+1 if > maxd
    from collections import deque
    dist = {s: 0}
    q = deque([s])
    while q:
        u = q.popleft()
        if dist[u] >= maxd:
            continue
        for v in adj[u]:
            if v not in dist:
                dist[v] = dist[u]+1
                if v == t:
                    return dist[v]
                q.append(v)
    return maxd+1

def try_build(n=15, target=23, seed=0):
    random.seed(seed)
    adj = {i:set() for i in range(n)}
    edges = []
    pairs = list(combinations(range(n),2))
    random.shuffle(pairs)
    for u,v in pairs:
        # adding edge u-v creates cycle of length 1+dist(u,v). need dist>=6
        d = bfs_dist(adj, u, v, 6)
        if d >= 6:  # dist is at least 6, cycle length >= 7
            adj[u].add(v); adj[v].add(u)
            edges.append((u,v))
            if len(edges) >= target:
                # try more
                pass
    return edges, adj

def is_4col(adj, n=15):
    import pycosat
    # SAT encoding
    # var (v,c) -> v*4 + c + 1
    clauses=[]
    for v in range(n):
        clauses.append([v*4+c+1 for c in range(4)])
        for c1 in range(4):
            for c2 in range(c1+1,4):
                clauses.append([-(v*4+c1+1), -(v*4+c2+1)])
    for u in adj:
        for v in adj[u]:
            if u<v:
                for c in range(4):
                    clauses.append([-(u*4+c+1), -(v*4+c+1)])
    r = pycosat.solve(clauses)
    if r == 'UNSAT': return None
    col = [0]*n
    for v in r:
        if v>0:
            idx=v-1
            col[idx//4]=idx%4
    return col

best=0
